import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([('https://www.odoo.com/documentation/20.0/contributing/development/git_guidelines.html','Odoo 20 – Git guidelines'),GD('gitworkflows','Git – gitworkflows'),GD('git-log'),GD('git-branch'),GD('git-config','Git – git-config (commit.template)'),('https://docs.gitlab.com/user/project/merge_requests/','GitLab Docs – Merge requests'),('https://docs.gitlab.com/user/project/repository/branches/protected/','GitLab Docs – Protected branches')])
def dia(vi):
    t=('Chiến lược nhánh gợi ý cho module khách hàng' if vi else 'A suggested branching strategy for a client module','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g10'%('vi' if vi else 'en'))
    def c(x,y,l='',ac=False): return '<circle class="%s" cx="%d" cy="%d" r="9" />\n'%('dg-accent' if ac else 'dg-box',x,y)
    b='<path class="dg-arrow" d="M20 90 H620" />\n'
    b+='<path class="dg-arrow" d="M80 90 L100 40 H200 L220 90" /><path class="dg-arrow" d="M260 90 L280 40 H380 L400 90" />\n'
    b+='<path class="dg-arrow" d="M440 90 L460 140 H600" />\n'
    for x in (20,80,220,260,400,440,540): b+=c(x,90)
    for x in (100,200,280,380): b+=c(x,40)
    for x in (460,600): b+=c(x,140,ac=True)
    b+='<text class="dg-title" x="20" y="120">main</text>\n'
    b+='<text class="dg-text" x="115" y="30">feature/…</text><text class="dg-text" x="295" y="30">feature/…</text>\n'
    b+='<text class="dg-text" x="215" y="115">MR</text><text class="dg-text" x="395" y="115">MR</text>\n'
    b+='<text class="dg-text" x="525" y="75">v1.0.0</text><text class="dg-text" x="470" y="162">release/1.0 (hotfix)</text>\n'
    b+='<text class="dg-text" x="10" y="185">%s</text>\n'%('Nhánh tính năng ngắn hạn vào main qua MR; tag đánh dấu bản phát hành;' if vi else 'Short-lived feature branches enter main through an MR; tags mark releases;')
    b+='<text class="dg-text" x="10" y="205">%s</text>\n'%('nhánh release chỉ nhận hotfix.' if vi else 'the release branch takes only hotfixes.')
    return fig('640 218',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a10');base(sb)
    sb.q('echo __pycache__/ >> .git/info/exclude')
    T1=sb.P('echo "    code = fields.Char(string=\'Mã khóa\')" >> models/course.py','git commit -aq -m "[IMP] vinc_course: thêm mã khóa học" -m "Phòng đào tạo tra cứu khóa theo mã nên mỗi khóa cần một trường mã riêng." -m "Closes #14"','git log -1')
    sb.q("sed -i \"s/Số giờ/Số giờ học/\" models/course.py;git commit -qam '[FIX] vinc_course: nhãn số giờ gây hiểu nhầm'")
    sb.q("echo '# doc' > README.md;git add README.md;git commit -qm '[ADD] vinc_course: README'")
    sb.q("echo 'x=1' > models/utils.py;git add .;git commit -qm '[REF] vinc_course: tách hàm tiện ích'")
    T2=sb.P('git log --oneline',"git log --oneline --grep='^\\[FIX\\]'",'git log --oneline -- models/','git shortlog -sn --no-merges HEAD')
    T7=sb.P('git tag -a v1.0.0 -m "Phát hành 1.0.0" HEAD~4','git log --oneline v1.0.0..HEAD',"git log --oneline v1.0.0..HEAD --grep='^\\[FIX\\]'")
    T3=sb.P('git check-ref-format --branch feature/course-price','git check-ref-format --branch "feature/course price"','git check-ref-format --branch 12-course-price')
    sb.q('printf "[TAG] module: tóm tắt thay đổi\\n\\nVì sao cần thay đổi (WHY).\\n\\nCloses #\\n" > ~/.gitmessage')
    T4=sb.P('git config --global commit.template ~/.gitmessage','git config --get commit.template','cat ~/.gitmessage')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Công cụ Git ai cũng như nhau; thứ làm nên nhóm làm việc trơn tru là quy ước chung.</strong> Bài này chốt ba quy ước: <strong>lời nhắn commit</strong> theo mẫu <code>[TAG] module: mô tả</code> của Odoo (giải thích <em>vì sao</em>), <strong>tên nhánh</strong> (<code>feature/</code>, <code>fix/</code>, <code>hotfix/</code>, mã issue) và <strong>chiến lược nhánh</strong> gọn cho module khách hàng (main được bảo vệ, nhánh ngắn hạn, merge request, tag phát hành). Có kèm lệnh <code>git log --grep</code> để thấy quy ước giúp tìm kiếm thế nào.','<strong>Everyone has the same Git tools; what makes a team run smoothly is shared conventions.</strong> This part settles three: the <strong>commit message</strong> following Odoo\'s <code>[TAG] module: description</code> pattern (explain <em>why</em>), <strong>branch names</strong> (<code>feature/</code>, <code>fix/</code>, <code>hotfix/</code>, issue number) and a lean <strong>branching strategy</strong> for client modules (protected main, short-lived branches, merge requests, release tags). It includes <code>git log --grep</code> to show how conventions make history searchable.')))
    o+=h2('vi-sao',t('Vì sao cần quy ước','Why conventions matter'))
    o+=p(t('Thử hình dung lịch sử repo toàn các dòng “update”, “fix”, “sửa lại”, “final”. Ba tháng sau khách hàng hỏi “từ khi nào trường mã khóa học bắt buộc nhập?”, và không ai trả lời được. Lịch sử Git chỉ có giá trị khi đọc được: nó là nhật ký mà <code>git log</code>, <code>git blame</code> và <code>git bisect</code> (bài 12) dựa vào. Tài liệu <code>gitworkflows</code> của Git tóm lại bằng quy tắc đầu tiên: chia thay đổi thành những bước logic nhỏ, mỗi bước là một commit nhất quán, chạy được độc lập và qua được bộ test. Điều đó làm review dễ hơn và lịch sử hữu ích hơn cho việc truy vết sau này.','Imagine a repo history made only of “update”, “fix”, “fixed again”, “final”. Three months later the customer asks “since when has the course code been mandatory?” and nobody can answer. Git history is only valuable when readable: it is the log that <code>git log</code>, <code>git blame</code> and <code>git bisect</code> (part 12) rely on. Git\'s own <code>gitworkflows</code> document sums it up in its first rule: cut your work into small logical steps, with every commit consistent, working on its own and passing the tests. That makes review easier and history more useful for later tracing.'))
    o+=h2('commit-message',t('Quy ước lời nhắn commit theo Odoo','The commit message convention, Odoo style'))
    o+=p(t('Hướng dẫn Git của Odoo mô tả lời nhắn gồm bốn phần: thẻ (tag), tên module, tiêu đề ngắn và mô tả đầy đủ. Mẫu là <code>[TAG] module: mô tả một câu ngắn</code>, tiêu đề lý tưởng dưới 50 ký tự, rồi một dòng trống và phần mô tả dài hơn, kết thúc bằng tham chiếu như <code>Closes #14</code> hay <code>Fixes #14</code>. Dùng tên kỹ thuật của module (<code>vinc_course</code>), vì tên hiển thị có thể đổi theo thời gian. Các thẻ theo tài liệu:','Odoo\'s Git guidelines describe a message with four parts: tag, module name, short header and full description. The pattern is <code>[TAG] module: one short sentence</code>, ideally under 50 characters, then a blank line and a longer description, ending with references such as <code>Closes #14</code> or <code>Fixes #14</code>. Use the module\'s technical name (<code>vinc_course</code>) because the display name can change over time. The tags according to the documentation:'))
    o+=tbl([t('Thẻ','Tag'),t('Dùng cho','Used for')],[['<code>[ADD]</code>',t('Thêm module hay thành phần mới','Adding a new module or component')],['<code>[IMP]</code>',t('Cải tiến, thay đổi tăng dần','Improvements and incremental changes')],['<code>[FIX]</code>',t('Sửa lỗi','Bug fixes')],['<code>[REF]</code>',t('Tái cấu trúc, viết lại lớn','Refactoring, heavy rewrites')],['<code>[REM]</code>',t('Xóa code, view hoặc module không dùng','Removing dead code, views or modules')],['<code>[REV]</code>',t('Revert một commit','Reverting a commit')],['<code>[MOV]</code>',t('Di chuyển file (không đổi nội dung)','Moving files (without changing content)')],['<code>[MERGE]</code>',t('Merge commit','Merge commits')],['<code>[REL]</code>',t('Commit phát hành phiên bản mới','Release commits')],['<code>[I18N]</code>',t('Thay đổi file dịch','Translation file changes')],['<code>[PERF]</code> / <code>[CLN]</code> / <code>[LINT]</code>',t('Tối ưu hiệu năng / dọn code / lint','Performance / cleanup / linting')]])
    o+=p(t('Điểm tinh tế nhất là tiêu đề nên ghép được thành một câu hợp lệ sau cụm “nếu áp dụng, commit này sẽ…”: <code>[IMP] vinc_course: thêm mã khóa học</code> đọc là “nếu áp dụng, commit này sẽ thêm mã khóa học”. Phần mô tả giải thích <strong>vì sao</strong>, vì “cái gì” đã nằm trong diff. Hãy tạo một commit như vậy:','The subtlest point is that the header should complete the sentence “this commit will…”: <code>[IMP] vinc_course: add a course code</code> reads as “this commit will add a course code”. The description explains <strong>why</strong>, since the “what” is already in the diff. Let us make such a commit:'))
    o+=T1
    o+=p(t('Mỗi <code>-m</code> thêm một đoạn, nên lệnh trên tạo tiêu đề, một đoạn lý do và dòng <code>Closes #14</code> (GitLab dùng nó để đóng issue khi merge, bài 5). Để tiện, bạn có thể cho Git mở sẵn một mẫu mỗi khi commit không có <code>-m</code>, bằng cấu hình <code>commit.template</code>:','Each <code>-m</code> adds a paragraph, so the command above creates the header, a paragraph of reasoning and a <code>Closes #14</code> line (GitLab uses it to close the issue on merge, part 5). For convenience you can have Git open a template whenever you commit without <code>-m</code>, using the <code>commit.template</code> setting:'))
    o+=T4
    o+=p(t('Quy ước có lợi ích thấy ngay khi tìm kiếm. Vì tiêu đề bắt đầu bằng thẻ, bạn lọc được mọi bản sửa lỗi bằng <code>--grep</code>, xem lịch sử của riêng thư mục <code>models/</code>, hay đếm đóng góp mỗi người:','A convention pays off immediately in searching. Because headers start with a tag, you can filter all bug fixes with <code>--grep</code>, look at the history of just the <code>models/</code> folder or count each person\'s contributions:'))
    o+=T2
    o+=p(t('Hai lời khuyên nữa từ tài liệu Odoo: tránh một commit đụng nhiều module cùng lúc (khó revert từng module), và tránh tiêu đề chung chung như “bugfix” hay “improvements”.','Two more pieces of advice from the Odoo documentation: avoid one commit touching several modules at once (hard to revert module by module), and avoid vague headers such as “bugfix” or “improvements”.'))
    o+=p(t('Một lợi ích nữa: viết changelog gần như miễn phí. Giả sử bản <code>v1.0.0</code> đã phát hành ở commit thứ hai trong lịch sử trên; mọi thứ sau đó là nội dung cho bản kế tiếp, và nhờ thẻ bạn tách riêng được các bản sửa lỗi để báo khách hàng:','One more benefit: writing a changelog becomes almost free. Suppose <code>v1.0.0</code> was released at the second commit of the history above; everything after it is the content of the next release, and thanks to the tags you can single out the bug fixes to tell the customer:'))
    o+=T7
    o+=p(t('Cú pháp <code>v1.0.0..HEAD</code> nghĩa là “các commit có trong <code>HEAD</code> mà không có trong <code>v1.0.0</code>”. Kết hợp với tag phát hành (bài 9), đây là cách nhóm trả lời câu hỏi “bản này khác bản trước ở đâu?” trong vài giây.','The syntax <code>v1.0.0..HEAD</code> means “commits in <code>HEAD</code> that are not in <code>v1.0.0</code>”. Together with release tags (part 9) it is how a team answers “what differs from the previous version?” in seconds.'))
    o+=p(t('Để mỗi commit làm đúng một việc ngay cả khi bạn lỡ sửa nhiều thứ trong cùng một file, hãy dùng <code>git add -p</code> (<code>--patch</code>): Git đưa từng đoạn thay đổi (<em>hunk</em>) ra và hỏi bạn có đưa vào staging không, nhờ vậy bạn tách “thêm trường” khỏi “dọn comment” thành hai commit riêng.','To keep each commit about one thing even when you changed several things in the same file, use <code>git add -p</code> (<code>--patch</code>): Git shows each changed chunk (<em>hunk</em>) and asks whether to stage it, letting you split “add a field” from “tidy a comment” into two separate commits.'))
    o+=h2('ten-nhanh',t('Quy ước đặt tên nhánh','Branch naming conventions'))
    o+=tbl([t('Tiền tố','Prefix'),t('Dùng cho','Used for'),t('Ví dụ','Example')],[['<code>feature/</code>',t('Tính năng mới','A new feature'),'<code>feature/course-price</code>'],['<code>fix/</code>',t('Sửa lỗi không khẩn','A non-urgent bug fix'),'<code>fix/duplicate-code</code>'],['<code>hotfix/</code>',t('Sửa gấp bản đang chạy','An urgent fix for the live version'),'<code>hotfix/1.0.1</code>'],['<code>release/</code>',t('Chuẩn bị hoặc duy trì một bản phát hành','Preparing or maintaining a release'),'<code>release/1.0</code>'],['<code>experiment/</code>',t('Thử nghiệm có thể bỏ','Throwaway experiments'),'<code>experiment/video</code>'],[t('mã issue','issue number'),t('Theo tài liệu GitLab, tiền tố mã issue giúp điền sẵn tiêu đề và đóng issue','Per GitLab\'s documentation an issue-number prefix prefills the title and closes the issue'),'<code>12-course-price</code>']])
    o+=p(t('Hãy viết chữ thường, nối bằng dấu gạch ngang và tránh ký tự đặc biệt. Git từ chối vài tên không hợp lệ; lệnh <code>git check-ref-format --branch</code> cho bạn kiểm tra trước:','Write lowercase, join words with hyphens and avoid special characters. Git rejects some invalid names; <code>git check-ref-format --branch</code> lets you test beforehand:'))
    o+=T3
    o+=h2('chien-luoc',t('Chiến lược nhánh gọn cho module khách hàng','A lean branching strategy for client modules'))
    o+=p(t('Tài liệu <code>gitworkflows</code> mô tả quy trình đầy đủ của chính dự án Git, với bốn nhánh tích hợp (<code>maint</code>, <code>master</code>, <code>next</code>, <code>seen</code>) và chính nó nhắc rằng với dự án nhỏ, ít người thì không cần quy trình đầy đủ. Với một nhóm làm module Odoo cho khách hàng, một phiên bản đơn giản là đủ và dễ giữ kỷ luật:','The <code>gitworkflows</code> document describes the full workflow of the Git project itself, with four integration branches (<code>maint</code>, <code>master</code>, <code>next</code>, <code>seen</code>), and it admits that a small team can skip much of it. For a team building Odoo modules for customers, a simple version is enough and easy to keep disciplined:'))
    o+=dia(vi)
    o+=tbl([t('Chiến lược','Strategy'),t('Cách hoạt động','How it works'),t('Hợp với','Fits')],[
        [t('<strong>Trunk-based / GitLab-style đơn giản</strong>','<strong>Trunk-based / simple GitLab style</strong>'),t('Một nhánh <code>main</code> được bảo vệ; nhánh tính năng ngắn hạn merge qua MR; tag cho mỗi bản phát hành','One protected <code>main</code>; short-lived feature branches merged through MRs; a tag for each release'),t('Nhóm nhỏ–vừa, phát hành thường xuyên (khuyến nghị)','Small to mid teams releasing often (recommended)')],
        [t('<strong>Thêm nhánh release</strong>','<strong>Add release branches</strong>'),t('Tách <code>release/x.y</code> khi cần duy trì nhiều bản cùng lúc; chỉ nhận hotfix','Branch <code>release/x.y</code> when several versions must be maintained; takes hotfixes only'),t('Khách hàng giữ bản cũ lâu','Customers who stay on old versions')],
        [t('<strong>Nhánh theo phiên bản Odoo</strong>','<strong>One branch per Odoo version</strong>'),t('Mỗi phiên bản Odoo có nhánh riêng (ví dụ <code>20.0</code>), tính năng tách từ đó','A branch per Odoo version (for example <code>20.0</code>), features branch off it'),t('Module phải hỗ trợ nhiều bản Odoo','Modules supporting several Odoo versions')],
        [t('<strong>Nhánh <code>develop</code> dài hạn</strong>','<strong>A long-lived <code>develop</code> branch</strong>'),t('Có thêm tầng tích hợp giữa tính năng và <code>main</code>','An extra integration layer between features and <code>main</code>'),t('Chỉ khi thật cần; dễ sinh xung đột lớn','Only when truly needed; breeds big conflicts')]])
    o+=p(t('GitLab cho phép chọn <em>cách merge</em> của dự án, trong đó có fast-forward (không tạo merge commit), nên thống nhất với nhóm: merge commit để thấy rõ từng MR, hay lịch sử thẳng bằng squash hoặc fast-forward. Dù chọn gì, hãy ghi lại trong README hoặc tài liệu đóng góp để người mới không phải đoán.','GitLab lets a project choose its <em>merge method</em>, including fast-forward (no merge commit), so agree as a team: merge commits to see each MR clearly, or a straight history through squash or fast-forward. Whatever you pick, write it down in the README or contributing guide so newcomers need not guess.'))
    o+=h2('quy-tac-nhom',t('Bộ quy tắc nhóm một trang','A one-page team rulebook'))
    o+=ul([t('Không commit thẳng lên <code>main</code>; mọi thay đổi đi qua merge request có ít nhất một người xem.','No direct commits to <code>main</code>; every change goes through a merge request that at least one person reviews.'),t('Một nhánh, một mục đích; sống tối đa vài ngày; xóa sau khi merge (cả cục bộ và remote).','One branch, one purpose; live at most a few days; delete after merging (local and remote).'),t('Lời nhắn commit theo <code>[TAG] module: mô tả</code> và nêu lý do ở phần thân.','Commit messages follow <code>[TAG] module: description</code> and give the reason in the body.'),t('Chỉ rebase nhánh riêng; không viết lại lịch sử đã chia sẻ (bài 8).','Rebase only your own branches; never rewrite shared history (part 8).'),t('Mỗi bản phát hành có tag annotated <code>vX.Y.Z</code> khớp với <code>version</code> trong manifest (bài 9).','Every release gets an annotated tag <code>vX.Y.Z</code> matching <code>version</code> in the manifest (part 9).'),t('Không commit bí mật; <code>.gitignore</code> có sẵn từ commit đầu (bài 2).','No secrets in commits; <code>.gitignore</code> exists from the first commit (part 2).')])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Lời nhắn vô nghĩa.</strong> “update”, “fix bug”, “sửa lại” không cho ai biết gì. Hãy viết tiêu đề đọc được như một câu và thêm lý do ở thân.','<strong>Meaningless messages.</strong> “update”, “fix bug” or “changed it again” tell nobody anything. Write a header that reads as a sentence and add the reason in the body.'),
        t('<strong>Một commit khổng lồ.</strong> Gom tính năng, sửa lỗi và dọn code vào một commit khiến review khó và không thể revert riêng từng phần. Chia nhỏ bằng <code>git add</code> từng file hoặc <code>git add -p</code>.','<strong>One giant commit.</strong> Bundling a feature, a bug fix and cleanup into one commit makes review hard and prevents reverting parts separately. Split with <code>git add</code> file by file or <code>git add -p</code>.'),
        t('<strong>Nhánh sống quá lâu.</strong> Nhánh tồn tại hàng tuần lệch xa <code>main</code> và gây xung đột lớn khi merge. Hãy cắt việc nhỏ hơn và kéo <code>main</code> về thường xuyên.','<strong>Branches that live too long.</strong> A branch that lasts weeks drifts far from <code>main</code> and causes big conflicts at merge. Cut the work smaller and bring <code>main</code> in often.'),
        t('<strong>Mỗi người một quy ước.</strong> Người viết “Feature:”, người viết “feat:”, người viết “[IMP]”: tìm kiếm trở nên vô nghĩa. Hãy chọn một mẫu, ghi vào tài liệu nhóm và để công cụ kiểm tra (bài 11).','<strong>Everyone with their own convention.</strong> One writes “Feature:”, another “feat:”, another “[IMP]”: searching becomes useless. Choose one pattern, document it and let tooling check it (part 11).'),
        t('<strong>Tên nhánh có dấu cách hoặc ký tự lạ.</strong> Git từ chối với <em>“is not a valid branch name”</em> như kết quả <code>check-ref-format</code> ở trên; dùng dấu gạch ngang.','<strong>Branch names with spaces or odd characters.</strong> Git refuses with <em>“is not a valid branch name”</em> as the <code>check-ref-format</code> result above shows; use hyphens.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Commit: <code>[TAG] module: mô tả</code>, tiêu đề ngắn, thân giải thích <em>vì sao</em>, kết thúc bằng <code>Closes #n</code>.','Commits: <code>[TAG] module: description</code>, short header, a body explaining <em>why</em>, ending with <code>Closes #n</code>.'),t('Nhánh: tiền tố <code>feature/</code>, <code>fix/</code>, <code>hotfix/</code>, <code>release/</code>; chữ thường nối bằng gạch ngang.','Branches: prefixes <code>feature/</code>, <code>fix/</code>, <code>hotfix/</code>, <code>release/</code>; lowercase joined with hyphens.'),t('Chiến lược: <code>main</code> được bảo vệ, nhánh ngắn hạn, merge request, tag phát hành, nhánh release khi cần.','Strategy: protected <code>main</code>, short-lived branches, merge requests, release tags and release branches when needed.'),t('Quy ước chỉ có tác dụng khi được viết ra và có công cụ kiểm tra.','A convention only works when written down and checked by tooling.')])
    o+=p(t('Quy ước viết trong tài liệu dễ bị quên lúc gấp. Bài tiếp theo biến chúng thành thứ máy kiểm tra giúp bạn: <strong>Git hook</strong> chặn commit sai mẫu hay lọt mật khẩu ngay trên máy, và <strong>GitLab CI</strong> chạy kiểm tra tự động cho module Odoo trong mỗi merge request.','Conventions in a document get forgotten under pressure. The next part turns them into something machines check for you: <strong>Git hooks</strong> that stop badly formatted commits or leaked passwords right on your machine, and <strong>GitLab CI</strong> that runs automatic checks for the Odoo module in every merge request.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
